export const MODES=['fan','beginner','math','analyst','player'];
const words={
 en:{intro:'Two teams try to put the ball into the other team’s goal. The team with more goals wins.',pass:'A pass sends the ball to a teammate. Completed means the teammate received it; intercepted means an opponent took it.',shot:'A shot is an attempt to score. A shot does not count as a goal unless it goes in.',pressure:'Pressure means a defender is trying to limit the ball carrier’s options. It does not prove the defender won the ball.',recovery:'A recovery means the team got the ball back. That gives it a new chance to build an attack.',restart:'Play is restarting. Watch which team has the ball and which goal it is moving toward.',goal:'A goal adds one to that team’s score. A tie means both teams have the same number of goals.',fulltime:'The match has ended. Compare the two goal totals to see the result.',why:'Why it matters',live:'JUST HAPPENED',math:'SHOW YOUR WORK',completion:'Pass completion',formula:'Completed passes ÷ attempted passes × 100',empty:'No pass attempts yet. The percentage is undefined, not zero.',meaning:'This is how often a pass reached a teammate. A high percentage alone does not prove attacking quality.',distance:'Pass distance',speed:'Average ball speed',rounding:'Coordinates and travel time are rounded. This is a synthetic straight-line estimate, not peak speed or video tracking.',waiting:'A completed pass will unlock the distance and speed example.',score:'Goals',tie:'The score is level.',home:'Harbor is ahead.',away:'Northbridge is ahead.'},
 es:{intro:'Dos equipos intentan meter el balón en la portería rival. Gana el equipo con más goles.',pass:'Un pase envía el balón a un compañero. Completado significa que lo recibió; interceptado, que lo tomó un rival.',shot:'Un tiro es un intento de marcar. Solo cuenta como gol si entra en la portería.',pressure:'La presión intenta limitar las opciones del jugador con balón. No demuestra que el defensor recuperara el balón.',recovery:'Una recuperación significa que el equipo volvió a tener el balón y puede iniciar otro ataque.',restart:'El juego se reinicia. Observa qué equipo tiene el balón y hacia qué portería avanza.',goal:'Un gol suma uno al marcador. Un empate significa que ambos equipos tienen los mismos goles.',fulltime:'El partido terminó. Compara los goles de los equipos para ver el resultado.',why:'Por qué importa',live:'ACABA DE PASAR',math:'PASO A PASO',completion:'Pases completados',formula:'Pases completados ÷ intentados × 100',empty:'Todavía no hay intentos de pase. El porcentaje no está definido; no es cero.',meaning:'Mide cuántos pases llegaron a un compañero. Un porcentaje alto no demuestra por sí solo calidad ofensiva.',distance:'Distancia del pase',speed:'Velocidad media del balón',rounding:'Las coordenadas y el tiempo están redondeados. Es una estimación sintética en línea recta, no velocidad máxima ni seguimiento por vídeo.',waiting:'Un pase completado permitirá ver el ejemplo de distancia y velocidad.',score:'Goles',tie:'El marcador está empatado.',home:'Harbor va ganando.',away:'Northbridge va ganando.'},
 pt:{intro:'Dois times tentam colocar a bola no gol adversário. Vence quem marcar mais gols.',pass:'Um passe envia a bola a um companheiro. Completo significa que ele recebeu; interceptado, que um adversário pegou a bola.',shot:'Uma finalização é uma tentativa de marcar. Só conta como gol se a bola entrar.',pressure:'Pressão tenta limitar as opções de quem está com a bola. Não prova que o defensor recuperou a bola.',recovery:'Uma recuperação significa que o time voltou a ter a bola e pode iniciar outro ataque.',restart:'O jogo está recomeçando. Veja quem tem a bola e para qual gol está avançando.',goal:'Um gol soma um ao placar. Um empate significa que os times têm o mesmo número de gols.',fulltime:'O jogo terminou. Compare os gols dos times para ver o resultado.',why:'Por que importa',live:'ACABOU DE ACONTECER',math:'PASSO A PASSO',completion:'Passes completos',formula:'Passes completos ÷ tentados × 100',empty:'Ainda não houve tentativas de passe. A porcentagem é indefinida, não zero.',meaning:'Mostra quantos passes chegaram a um companheiro. Uma porcentagem alta não prova qualidade ofensiva por si só.',distance:'Distância do passe',speed:'Velocidade média da bola',rounding:'Coordenadas e tempo são arredondados. É uma estimativa sintética em linha reta, não velocidade máxima ou rastreamento de vídeo.',waiting:'Um passe completo libera o exemplo de distância e velocidade.',score:'Gols',tie:'O placar está empatado.',home:'Harbor está na frente.',away:'Northbridge está na frente.'}
};
export function lesson(mode,stats,event,pass,language='en'){
 const w=words[language]||words.en,s=stats;
 if(mode==='beginner'){const type=event?.outcome==='goal'?'goal':event?.type;return {kicker:w.live,title:type?`${event.team==='home'?'Harbor':'Northbridge'} · ${type.replaceAll('_',' ')}`:w.why,body:w[type]||w.intro,equation:s?`${w.score}: Harbor ${s.score.home} – ${s.score.away} Northbridge`:'Harbor → goal ← Northbridge',detail:s?(s.score.home===s.score.away?w.tie:s.score.home>s.score.away?w.home:w.away):w.intro};}
 const attempted=s?.passes.home||0,completed=s?.completed.home||0;
 const result={kicker:w.math,title:`Harbor · ${w.completion}`,body:w.formula,equation:attempted?`${completed} ÷ ${attempted} × 100 ≈ ${Math.round(completed/attempted*100)}%`:w.empty,detail:w.meaning,examples:[]};
 if(pass?.from&&pass?.to&&pass.travel_seconds>0){const dx=pass.to[0]-pass.from[0],dy=pass.to[1]-pass.from[1],distance=Math.hypot(dx,dy),speed=distance/pass.travel_seconds;result.examples=[{title:w.distance,equation:`√((${dx.toFixed(1)})² + (${dy.toFixed(1)})²) = ${distance.toFixed(1)} m`},{title:w.speed,equation:`${distance.toFixed(1)} m ÷ ${pass.travel_seconds.toFixed(1)} s = ${speed.toFixed(1)} m/s; × 3.6 = ${(speed*3.6).toFixed(1)} km/h`}];result.note=w.rounding;}else result.note=w.waiting;
 return result;
}
export function learningObservation(mode,stats,language){const l=lesson(mode,stats,null,null,language);return mode==='beginner'?`${l.equation}. ${l.detail} ${l.body}`:`${l.body}: ${l.equation}. ${l.detail}`;}
